// Local Project Components
// SFCC-863 — Header/Footer/DrawerMenu/ListMenu are all already overridden; imported via
// relative paths rather than the base SFCC path per overrideStyling.md's "importing an
// already-overridden component" rule. The webpack ccExtensibility resolver would redirect
// either path form correctly in the real dev server/production build, but Storybook and
// Vitest skip that resolver entirely, so a base-path import here would silently exercise
// the unstyled base SFCC version in any story/test that renders this component.
import AboveHeader from '@salesforce/retail-react-app/app/components/_app/partials/above-header';
